def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find a full-width separator row.
    sep = next((r for r, row in enumerate(g)
                if len(set(row)) == 1 and row[0] != 3), None)
    if sep is None:
        return g

    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    obj_color = next((v for row in g for v in row if v not in (bg, g[sep][0])), None)
    if obj_color is None:
        return g

    cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] == obj_color]
    min_r, max_r = min(r for r, c in cells), max(r for r, c in cells)
    if max_r < sep:
        shift = sep - 1 - max_r
        mark_r = min_r + shift - 1
    else:
        shift = sep + 1 - min_r
        mark_r = max_r + shift + 1

    for r, c in cells:
        g[r][c] = bg
    for r, c in cells:
        nr = r + shift
        if 0 <= nr < h:
            g[nr][c] = obj_color
    if 0 <= mark_r < h:
        g[mark_r] = [8] * w
    return g
